# Hand-authored blind judgments (lane B, T4). Executed by phase1.py.

def C1mod(defn, buffers, conf="high", neighbor="none", extra_counter="No reinforcing prominent strong anionic; refatting/conditioning counter-signals recorded only."):
    return P("moderate", conf,
             f"Moderate: C1 ether/sulfonate chassis - defining anionic {defn} buffered by prominent {buffers}; no prominent reinforcing strong anionic (C3, C4, C1).",
             extra_counter, neighbor, rule=["C3", "C4", "C1"])

